import{_ as a,o as l,c as r,a2 as t}from"./chunks/framework.BEUshCVJ.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/changelog.md","filePath":"zh/reference/changelog.md","lastUpdated":1792860039000}'),o={name:"zh/reference/changelog.md"};function i(n,e,h,d,s,c){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p>MeetCue 的重要变更记录。版本号遵循<a href="https://semver.org/lang/zh-CN/" target="_blank" rel="noreferrer">语义化版本</a>。</p><h2 id="_0-1-2-—-2026-10-24" tabindex="-1">0.1.2 — 2026-10-24 <a class="header-anchor" href="#_0-1-2-—-2026-10-24" aria-label="Permalink to &quot;0.1.2 — 2026-10-24&quot;">​</a></h2><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>价格不再内置在程序中。MeetCue 会下载对照各供应商官网核对过的<a href="/meetcue/zh/reference/pricing">价格参考</a>，保留最近一份供离线使用，并可在 <strong>设置 › 供应商与费用</strong> 中更新。</li><li>更紧凑的 <strong>模型与价格</strong> 布局：每个模型一行，显示单价和预计每小时费用，按费用排序，并标出 <strong>最省</strong> 和 <strong>最快</strong>。API 密钥每个供应商一行。</li><li>没有公开价格的模型改为链接到供应商官网价格页，不再显示 <strong>价格未知</strong>。</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>Deepgram Nova-3 之前按多语言费率计算。MeetCue 识别中文或英文时只请求单一语言，费用为每分钟 0.0077 美元。</li></ul><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>Claude Sonnet 5、Claude Opus 5 和 Claude Fable 5.1 的价格。</li></ul><h2 id="_0-1-1-—-2026-10-24" tabindex="-1">0.1.1 — 2026-10-24 <a class="header-anchor" href="#_0-1-1-—-2026-10-24" aria-label="Permalink to &quot;0.1.1 — 2026-10-24&quot;">​</a></h2><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>Deepgram、Anthropic 和 OpenAI 兼容接口的密钥验证失败，使用它们的会话也无法开始：此前只接入了 Soniox。</li><li>在设置向导中点 <strong>完成</strong> 后，窗口变成空白而不是关闭。</li><li>设置中的开关滑块位置偏移。</li></ul><h3 id="移除" tabindex="-1">移除 <a class="header-anchor" href="#移除" aria-label="Permalink to &quot;移除&quot;">​</a></h3><ul><li>Amazon Bedrock。要点生成请使用 Anthropic 或 OpenAI 兼容接口。</li></ul><h2 id="_0-1-0-—-2026-10-23" tabindex="-1">0.1.0 — 2026-10-23 <a class="header-anchor" href="#_0-1-0-—-2026-10-23" aria-label="Permalink to &quot;0.1.0 — 2026-10-23&quot;">​</a></h2><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>会议模式：实时问题检测与提前触发，约一秒半内给出编号要点，问题队列，已讲要点打勾。</li><li>不抢焦点的悬浮面板，支持完整与迷你两种形态、鼠标穿透和共享屏幕时隐藏。</li><li>语音识别支持 Soniox 和 Deepgram；要点生成支持 Anthropic、Amazon Bedrock 和 OpenAI 兼容接口。</li><li>延迟探测：自动选择端点、估算费用并对组合排序。</li><li>价格表、用量统计、预算提醒和 CSV 导出。</li><li>练习模式：导入字幕和问题列表并在预览中编辑，用系统语音朗读问题，支持真实识别和模拟延迟、追问、四档提示难度，以及可导出为 Markdown 的复盘报告。</li><li>支持 txt、md、docx 和 pdf 格式的会前资料。</li><li>中英双语界面与文档。</li><li>带解决办法链接的错误码、诊断信息导出、<code>--demo</code> 与 <code>--self-test</code>。</li></ul>',17)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
